mapper.select:
WITH TMP AS ( select MAX(BOOK_ORDER), BOOKSET_ID, HAPPEN_DATE, TABLE_ID, TRADE_ID, BOK_DETAIL_ID, BUSI_ID, SUBJECT_NO, DETAIL_SUBJECT_NO, O_AMT_HAPPEN_DATE, B_AMT_HAPPEN_DATE FROM BOK_BOOKDETAIL_CURRENT WHERE BOOKSET_ID = #{booksetId} AND HAPPEN_DATE >= to_date(#{startDate}, 'yyyy-MM-dd') AND HAPPEN_DATE <= to_date(#{endDate}, 'yyyy-MM-dd') AND (DETAIL_SUBJECT_NO = #{id} OR SUBJECT_NO =#{id})
AND BUSI_ID = #{detailSubjectNoTail}
GROUP BY BOOKSET_ID, HAPPEN_DATE, TABLE_ID, TRADE_ID, BOK_DETAIL_ID, BUSI_ID, SUBJECT_NO, DETAIL_SUBJECT_NO, O_AMT_HAPPEN_DATE, B_AMT_HAPPEN_DATE ) select A.BOOK_DATE AS bookDate, A.VOUCH_NUM AS seqNo, NVL(C.FINPROD_NAME,B.BUSI_ID） AS finprodAbbr, NVL(B.DETAIL_SUBJECT_NAME，B.SUBJECT_NAME) AS subjectName, B.CD_FLAG AS cdFlag, B.CCY AS ccyFmt, B.B_CCY AS bCcyFmt, B.HAPPEN_AMT AS happenAmt, B.B_HAPPEN_AMT AS bHappenAmt, B.HAPPEN_NUMBER AS happenNumber, TMP.O_AMT_HAPPEN_DATE AS marketValue, TMP.B_AMT_HAPPEN_DATE AS valuePercent, B.TRADE_ID AS tradeId, B.TABLE_ID AS ywlb FROM BOK_VOUCH_MAIN A INNER JOIN BOK_VOUCH_DETAIL B ON A.VOUCH_NUM = B.VOUCH_NUM INNER JOIN TMP ON TMP.BOOKSET_ID = A.BOOKSET_ID AND TMP.HAPPEN_DATE = B.HAPPEN_DATE AND TMP.TRADE_ID = B.TRADE_ID AND TMP.TABLE_ID = B.TABLE_ID AND TMP.DETAIL_SUBJECT_NO = B.DETAIL_SUBJECT_NO AND TMP.SUBJECT_NO = B.SUBJECT_NO AND TMP.BUSI_ID = B.BUSI_ID LEFT JOIN fin_product C ON C.FINPROD_ID = B.BUSI_ID WHERE A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE >= to_date(#{startDate}, 'yyyy-MM-dd') AND A.BOOK_DATE <= to_date(#{endDate}, 'yyyy-MM-dd') AND (B.DETAIL_SUBJECT_NO = #{id} OR B.SUBJECT_NO = #{id})
AND B.BUSI_ID = #{detailSubjectNoTail}
